            "items": {
              "maximum": 10,
              "minimum": 1,
              "type": "integer"
            },
            "maxItems": 10,
            "type": "array",
            "uniqueItems": true
          }
        },
        "required": [
          "ask",
          "support_status",
          "supporting_evidence_ranks"
        ],
        "type": "object"
      },
      "maxItems": 8,
      "minItems": 1,
